 root.innerHTML=A.state.cart.map((x,i)=>`<div class="cart-line pos-cart-line"><div class="cart-main"><div class="cart-line-title"><b>${esc(x.name)}</b><button class="cart-remove" data-remove="${i}" title="حذف الصنف من الفاتورة" aria-label="حذف ${esc(x.name)}">×</button></div><small>${money(x.unitPrice)} / ${unitLabel(x.unit)}</small><select class="line-unit" data-unit-index="${i}"><option value="pack" ${x.unit==='pack'?'selected':''}>علبة</option><option value="strip" ${x.unit==='strip'?'selected':''}>شريط</option><option value="unit" ${x.unit==='unit'?'selected':''}>وحدة</option></select></div><div class="qty"><button data-dec="${i}">−</button><input class="cart-qty-input" data-qty-index="${i}" type="number" min="1" step="1" value="${x.qty}" inputmode="numeric" aria-label="كمية ${esc(x.name)}"><button data-inc="${i}">+</button></div><div class="line-total">${money(x.qty*x.unitPrice)}</div></div>`).join('')||`<div class="pos-cart-empty"><b>الفاتورة فارغة</b><small>ابحث عن دواء أو امسح الباركود لبدء البيع.</small></div>`;
 const setCartQty=(i,q)=>{if(!A.state.cart[i])return;const next=Math.max(0,Math.floor(num(q)||0));if(next<=0)A.state.cart.splice(i,1);else A.state.cart[i].qty=next;posProfitContext=null;posProfitSignature='';return renderCart()};A.$$('[data-inc]').forEach(b=>b.onclick=()=>setCartQty(+b.dataset.inc,num(A.state.cart[+b.dataset.inc]?.qty)+1));A.$$('[data-dec]').forEach(b=>b.onclick=()=>setCartQty(+b.dataset.dec,num(A.state.cart[+b.dataset.dec]?.qty)-1));A.$$('[data-remove]').forEach(b=>b.onclick=()=>setCartQty(+b.dataset.remove,0));A.$$('[data-qty-index]').forEach(inp=>{const commit=()=>setCartQty(+inp.dataset.qtyIndex,Math.max(1,Math.floor(num(inp.value)||1)));inp.oninput=commit;inp.onchange=commit;inp.onblur=commit});
 A.$$('[data-unit-index]').forEach(s=>s.onchange=async()=>{const i=+s.dataset.unitIndex,p=await get('products',A.state.cart[i].productId);A.state.cart[i].unit=s.value;A.state.cart[i].factor=unitFactor(p,s.value);A.state.cart[i].unitPrice=A.offerPrice?await A.offerPrice(p,s.value):unitPrice(p,s.value);renderCart()});
 const subtotal=A.state.cart.reduce((a,x)=>a+x.qty*x.unitPrice,0),showProfit=!!A.canViewProfit?.(),profit=showProfit&&A.state.cart.length?await cartProfitSnapshot():{profit:0,marginPct:0,safeDiscount:0,unknownLines:0,fallbackLines:0,stockShort:false};
 if(renderToken!==posRenderSeq)return;
 const safeText=profit.safeDiscount===null?'غير متاح':money(profit.safeDiscount),note=[profit.unknownLines?`${profit.unknownLines} بند بدون تكلفة مؤكدة`:null,profit.fallbackLines?`تم استخدام سعر الشراء كتكلفة تقديرية في ${profit.fallbackLines} بند`:null,profit.stockShort?'الكمية الحالية تتجاوز المخزون المتاح لبعض الأصناف':null].filter(Boolean).join(' • '),profitMarkup=showProfit?`<div class="profit-insight staff-only ${posProfitHidden?'is-hidden':''}" data-no-print="true"><div class="profit-insight-head"><b>مؤشر الربح والخصم</b><button id="profitToggle" class="profit-toggle" type="button">${posProfitHidden?'إظهار':'إخفاء'}</button></div><div class="profit-grid"><div class="profit-metric ${profitTone(profit.marginPct)}"><small>ربح الفاتورة المتوقع</small><strong>${profit.unknownLines?'≈ ':''}${money(profit.profit)}</strong></div><div class="profit-metric ${profitTone(profit.marginPct)}"><small>هامش الربح</small><strong>${profit.marginPct.toFixed(1)}%</strong></div><div class="profit-metric ${profit.safeDiscount===null?'warn':profit.safeDiscount<=0?'danger':''}"><small>خصم آمن حتى</small><strong>${safeText}</strong></div></div>${note?`<small class="profit-note">${esc(note)}</small>`:''}</div>`:'';
 tot.innerHTML=`<div class="total-box"><div class="total-row"><span>إجمالي الأصناف</span><b>${money(subtotal)}</b></div><div class="total-row"><span>عدد البنود</span><span>${A.state.cart.length}</span></div>${profitMarkup}<div class="total-row grand"><span>المطلوب قبل الخصم</span><span>${money(subtotal)}</span></div><button id="payBtn" class="btn primary wide" ${A.state.cart.length?'':'disabled'}>الدفع وإتمام البيع</button></div>`;
