async function addToCart(pid){const p=posProductHints.get(pid)||await get('products',pid);if(!p||p.status==='inactive')return;const existing=A.state.cart.find(x=>x.productId===pid&&x.unit==='pack');if(existing)existing.qty++;else{posProfitContext=null;posProfitSignature='';const price=A.offerPrice?await A.offerPrice(p,'pack'):unitPrice(p,'pack');A.state.cart.push({productId:pid,name:p.name,barcode:p.barcode||'',gtin:p.gtin||'',itemCodeType:p.itemCodeType||'GS1',itemCode:p.itemCode||p.gtin||p.barcode||'',taxType:p.taxType||'',taxRate:num(p.taxRate),qty:1,unit:'pack',factor:packSize(p),unitPrice:price,baseUnitPrice:unitPrice(p,'pack')})}await renderCart();const q=A.$('#posSearch');if(q){q.value='';q.focus();const grid=A.$('#productGrid');if(grid)grid.innerHTML=`<div class="pos-search-empty compact"><b>تمت الإضافة للفاتورة</b><small>امسح باركود آخر أو ابدأ بحثًا جديدًا.</small></div>`;const meta=A.$('#posResultMeta');if(meta)meta.innerHTML=''}}

