 const localBarcode=new Map(),localIndex=[];if(!remote)for(const p of localProducts){for(const code of [p.barcode,p.gtin,p.itemCode,...(p.barcodes||[])].filter(Boolean))localBarcode.set(String(code).trim(),p);localIndex.push({p,text:[p.name,p.barcode,p.active,p.activeIngredient,p.company,p.gtin,p.itemCode,p.category,p.location].join(' ').toLowerCase()})}
 async function searchProducts(q=''){const category=A.$('#posCategory')?.value||'',term=String(q||'').trim();if(!term&&!category)return[];if(remote)return window.PharmaRemote.posSearch(term,{branchId,category,limit:60,availableOnly:A.$('#posAvailableOnly')?.checked!==false});const exact=term?localBarcode.get(term):null,pool=exact?[exact]:localIndex.filter(x=>(!term||x.text.includes(term.toLowerCase()))&&(!category||x.p.category===category)).map(x=>x.p);const stock=new Map();for(const b of localBatches){if((branchId&&b.branchId&&b.branchId!==branchId)||(b.status||'available')!=='available'||daysTo(b.expiry)<0)continue;stock.set(b.productId,(stock.get(b.productId)||0)+num(b.qtyBase))}const rows=pool.slice(0,60).map(p=>({...p,stockBase:stock.get(p.id)||0}));return A.$('#posAvailableOnly')?.checked===false?rows:rows.filter(p=>num(p.stockBase)>0)}
