 let posSearchSeq=0;
 async function draw(q=''){const seq=++posSearchSeq,term=String(q||'').trim(),category=A.$('#posCategory')?.value||'',rows=await searchProducts(term);if(seq!==posSearchSeq)return;if(!term&&!category){A.$('#productGrid').innerHTML=`<div class="pos-search-empty"><div class="pos-search-icon">⌕</div><b>ابدأ بكتابة اسم الدواء أو امسح الباركود</b><small>لن نملأ الشاشة باقتراحات غير مطلوبة — النتائج تظهر فقط عند البحث.</small></div>`;A.$('#posResultMeta').innerHTML='';return}posProductHints=new Map(rows.map(p=>[p.id,p]));A.$('#productGrid').innerHTML=rows.map(p=>`<div class="product-card pos-result-card ${num(p.stockBase)<1?'out-of-stock':''}"><div class="product-main-info"><div class="product-top"><strong>${esc(p.name)}</strong>${p.rx?badge('Rx','warn'):''}</div><small>${esc(p.active||p.activeIngredient||'')} • ${esc(p.company||p.manufacturer||'')}</small><small>المتاح: ${(num(p.stockBase)/Math.max(1,packSize(p))).toFixed(1)} علبة${p.nearestExpiry?` • صلاحية ${A.fmtDate(p.nearestExpiry)}`:''}</small></div><div class="product-result-side"><div class="price">${money(p.sellPrice)}</div>${num(p.stockBase)>0?`<button class="btn tiny primary" data-add="${p.id}">إضافة</button>`:`<button class="btn tiny warn" data-alt="${p.id}">عرض البدائل</button>`}</div></div>`).join('')||empty('لا توجد نتائج مطابقة');A.$('#posResultMeta').innerHTML=`<div class="filter-summary"><span><b>${rows.length}</b> نتيجة</span><span>اختر الصنف لإضافته للفاتورة</span></div>`;A.$$('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));A.$$('[data-alt]').forEach(b=>b.onclick=()=>showAlternatives(b.dataset.alt));window.dispatchEvent(new CustomEvent('elhafez:pos-grid-rendered',{detail:{count:rows.length}}))}
