async function checkout(o,subtotal,deliveryFee=0){
 if(window.PharmaRemote?.enabled&&!window.PharmaRemote.inAtomic()){const btn=A.$('#confirmCheckout');if(btn?.dataset.busy==='1')return;const oldText=btn?.textContent||'';if(btn){btn.dataset.busy='1';btn.disabled=true;btn.textContent='جاري الاعتماد…'}try{const committed=await window.PharmaRemote.atomic(()=>checkout(o,subtotal,deliveryFee),'sale');if(!committed?.id)throw new Error('SALE_COMMIT_RESULT_MISSING');A.state.cart=[];posProfitContext=null;posProfitSignature='';linkedOrderId=null;linkedPrescriptionId=null;closeModal();toast(`تم حفظ الفاتورة ${committed.no}`);await window.PharmaRemote.forceRefresh?.('sales');await A.render();await showReceipt(committed);return committed}catch(e){toast(window.PharmaRemote?.friendlyError?.(e)||'تعذر إتمام البيع. لم يتم حفظ أي جزء من العملية.','danger');return null}finally{if(btn?.isConnected){btn.dataset.busy='0';btn.disabled=false;btn.textContent=oldText}}}
 const F=window.ElhafezFinance;
 let discount=Math.max(0,Math.min(num(o.discount),subtotal)),customer=o.customerId?await get('customers',o.customerId):null,pointsDiscount=0;
 const maxDisc=num(A.state.user?.maxDiscountPercent??100);if(subtotal>0&&discount/subtotal*100>maxDisc+0.001){toast(`صلاحيتك تسمح بخصم حتى ${maxDisc}% فقط`,'danger');return}
 if(o.payment==='credit'&&!A.canAction?.('creditSale')){toast('لا توجد صلاحية للبيع الآجل','danger');return}
 if(o.redeemPoints==='on'&&customer){const value=num(A.state.settings?.loyaltyRedeemValue)||.1;pointsDiscount=Math.min(num(customer.points)*value,subtotal-discount);const used=Math.ceil(pointsDiscount/value);customer.points=Math.max(0,num(customer.points)-used)}
 if(o.payment==='credit'&&!customer){toast('البيع الآجل يحتاج اختيار عميل','danger');return}
 let contract=null,contractDiscount=0;
 const baseAfter=Math.max(0,subtotal-discount-pointsDiscount);
 if(o.payment==='insurance'){
   if(!customer){toast('التأمين يحتاج اختيار عميل','danger');return}
   if(!o.contractId){toast('اختر التعاقد/شركة التأمين','danger');return}
   contract=await get('contracts',o.contractId);if(!contract){toast('التعاقد غير موجود','danger');return}
   contractDiscount=baseAfter*Math.min(100,Math.max(0,num(contract.discountPercent)))/100;
 }
 const finance=F.computeSale(A.state.cart,{discount,pointsDiscount,contractDiscount,deliveryFee,pricesIncludeTax:A.state.settings?.salePricesIncludeTax!==false,taxRegistered:A.state.settings?.taxRegistered!==false});
 const total=finance.total,merchandiseTotal=finance.merchandiseGross;
 let customerPay=total,claimAmount=0;
 if(o.payment==='insurance'){
   const share=Math.min(100,Math.max(0,num(contract.patientSharePercent))),covered=num(contract.coverageLimit)>0?Math.min(total,num(contract.coverageLimit)):total;
   claimAmount=F.money(covered*(100-share)/100);customerPay=F.money(total-claimAmount);
 }
 if(o.payment==='split'){const paid=F.money(num(o.splitCash)+num(o.splitCard)+num(o.splitWallet));if(Math.abs(paid-total)>0.01){toast(`إجمالي الدفع المختلط يجب أن يساوي ${money(total)}`,'danger');return}}
 // Resolve only the sellable FEFO batches for the products on this invoice.
 const productIds=[...new Set(A.state.cart.map(x=>x.productId))];
 const batchList=window.PharmaRemote?.enabled?await window.PharmaRemote.sellableBatches(productIds,A.state.settings?.branchId):(await all('batches'));
 const plans=[];let cost=0;
 for(const line of finance.lines){let need=num(line.qty)*num(line.factor);const candidates=batchList.filter(b=>b.productId===line.productId&&num(b.qtyBase)>0&&(b.status||'available')==='available'&&daysTo(b.expiry)>=0&&(!A.state.settings?.branchId||!b.branchId||b.branchId===A.state.settings.branchId)).sort((a,b)=>new Date(a.expiry)-new Date(b.expiry));
   if(candidates.reduce((a,b)=>a+num(b.qtyBase),0)<need){toast(`المخزون غير كافٍ للصنف ${line.name}`,'danger');return}
   const allocations=[];for(const b of candidates){if(need<=0)break;const already=plans.flatMap(p=>p.allocations).filter(x=>x.batchId===b.id).reduce((a,x)=>a+x.qtyBase,0),available=num(b.qtyBase)-already,take=Math.min(need,available);if(take>0){allocations.push({batchId:b.id,batchNo:b.batchNo,qtyBase:take,costPerBase:num(b.costPerBase)});need-=take;cost+=take*num(b.costPerBase)}}plans.push({line,allocations});
 }
 const saleId=id('sale'),saleNo=window.PharmaRemote?.enabled?`PENDING-${saleId}`:'S-'+String((await all('sales')).length+1).padStart(4,'0'),at=new Date().toISOString();
 for(const p of plans){for(const x of p.allocations){const b=await get('batches',x.batchId);b.qtyBase=num(b.qtyBase)-x.qtyBase;await put('batches',b);await A.stockMove(p.line.productId,b.id,-x.qtyBase,'sale',saleNo,`بيع ${p.line.name}`)}}
 const lines=plans.map(p=>({...p.line,allocations:p.allocations})),paymentLabel={cash:'نقدي',card:'بطاقة',wallet:'محفظة',credit:'آجل',insurance:'تأمين/تعاقد',split:'مختلط'}[o.payment]||o.payment;
 const sale={id:saleId,no:saleNo,at,lines,subtotal:finance.subtotal,discount:finance.discount,pointsDiscount:finance.pointsDiscount,contractDiscount:finance.contractDiscount,deliveryFee:finance.deliveryFee,taxTotal:finance.taxTotal,salesNet:finance.salesNet,pricesIncludeTax:finance.pricesIncludeTax,taxRegistered:A.state.settings?.taxRegistered!==false,total,cost:F.money(cost),grossProfit:F.money(finance.salesNet-cost),payment:o.payment,paymentLabel,customerPay,claimAmount,contractId:contract?.id||null,contractName:contract?.name||'',customerId:customer?.id||null,customerName:customer?.name||'',note:o.note||'',userId:A.state.user?.id||null,userName:A.state.user?.name||'',shiftId:(await A.currentShift())?.id||null,branchId:A.state.settings?.branchId||null,status:'completed',clinicalReviewed:o.clinicalReviewed==='on',creditBalance:o.payment==='credit'?total:0,returnedAmount:0,orderId:linkedOrderId,prescriptionId:linkedPrescriptionId,complianceData:o.prescriptionNo?{patientName:o.patientName||customer?.name||'',patientIdNo:o.patientIdNo||'',prescriptionNo:o.prescriptionNo||'',prescriptionDate:o.prescriptionDate||'',doctorName:o.doctorName||'',doctorLicenseNo:o.doctorLicenseNo||'',complianceDocument:o.complianceDocument||'',serialCodes:String(o.serialCodes||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}:null};
 await put('sales',sale);
 if(customer){if(o.payment==='credit')customer.balance=num(customer.balance)+total;const earnEvery=num(A.state.settings?.loyaltyEarnEvery)||10;customer.points=num(customer.points)+Math.floor(total/earnEvery);await put('customers',customer)}
 const revenueCredits=[{accountCode:'4000',account:'المبيعات',debit:0,credit:finance.salesNet},...(finance.taxTotal>0?[{accountCode:'2100',account:'ضريبة مخرجات مستحقة',debit:0,credit:finance.taxTotal}]:[]),...(finance.deliveryFee>0?[{accountCode:'4100',account:'إيرادات التوصيل',debit:0,credit:finance.deliveryFee}]:[]),{accountCode:'5000',account:'تكلفة البضاعة المباعة',debit:cost,credit:0},{accountCode:'1200',account:'المخزون',debit:0,credit:cost}];
 if(o.payment==='insurance'){
   if(customerPay>0)await A.cashMove('sale',customerPay,saleNo,`تحمل عميل - ${saleNo}`,'cash','in');await put('claims',{id:id('clm'),contractId:contract.id,contractName:contract.name,customerId:customer.id,customerName:customer.name,saleId,saleNo,at,amount:claimAmount,status:'pending'});
   await A.journal(saleNo,'sale_insurance',[{accountCode:'1000',account:'الخزينة',debit:customerPay,credit:0},{accountCode:'1150',account:'مطالبات التأمين',debit:claimAmount,credit:0},...revenueCredits],`فاتورة تأمين ${saleNo}`);
 }else if(o.payment==='split'){
   const parts=[['cash',num(o.splitCash),'1000','الخزينة'],['card',num(o.splitCard),'1020','بطاقات'],['wallet',num(o.splitWallet),'1020','محافظ إلكترونية']].filter(x=>x[1]>0);for(const [m,amt] of parts)await A.cashMove('sale',amt,saleNo,`جزء من فاتورة ${saleNo}`,m,'in');sale.splitPayments=Object.fromEntries(parts.map(([m,amt])=>[m,amt]));await put('sales',sale);await A.journal(saleNo,'sale_split',[...parts.map(([,amt,code,acc])=>({accountCode:code,account:acc,debit:amt,credit:0})),...revenueCredits],`فاتورة بيع مختلطة ${saleNo}`);
 }else{
   if(o.payment!=='credit')await A.cashMove('sale',total,saleNo,`فاتورة بيع ${saleNo}`,o.payment,'in');const code=o.payment==='credit'?'1100':o.payment==='cash'?'1000':'1020';await A.journal(saleNo,'sale',[{accountCode:code,account:o.payment==='credit'?'عملاء':o.payment==='cash'?'الخزينة':'وسائل تحصيل',debit:total,credit:0},...revenueCredits],`فاتورة بيع ${saleNo}`);
 }
 if(linkedOrderId){const ord=await get('orders',linkedOrderId);if(ord){ord.status='completed';ord.saleId=saleId;ord.updatedAt=at;await put('orders',ord)}}if(linkedPrescriptionId){const pr=await get('prescriptions',linkedPrescriptionId);if(pr){pr.status='dispensed';pr.saleId=saleId;await put('prescriptions',pr)}}
 await audit('فاتورة بيع',`${saleNo} — ${total} — ${paymentLabel}`);return sale;
}


function defaultProviderBrand(){return{enabled:true,name:'Elhafez Technology',phone:'',whatsapp:'',email:'',website:'',extra:''}}
function readCachedProviderBrand(){try{const x=JSON.parse(localStorage.getItem('elhafez_provider_brand')||'null');return x&&typeof x==='object'?{...defaultProviderBrand(),...x}:defaultProviderBrand()}catch{return defaultProviderBrand()}}
async function refreshProviderBrand(force=false){if(!force&&A.state.providerBrand)return A.state.providerBrand;try{const r=await fetch(`/api/provider-branding${force?'?refresh=1':''}`,{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error('PROVIDER_BRAND_UNAVAILABLE');const x={...defaultProviderBrand(),...(await r.json()||{})};A.state.providerBrand=x;try{localStorage.setItem('elhafez_provider_brand',JSON.stringify(x))}catch{}return x}catch{const x=readCachedProviderBrand();A.state.providerBrand=x;return x}}
A.refreshProviderBrand=refreshProviderBrand;
function providerReceiptLine(){const p=A.state.providerBrand||readCachedProviderBrand();if(p.enabled===false)return'';const phone=String(p.phone||'').trim(),details=[];if(p.whatsapp&&String(p.whatsapp).trim()!==phone)details.push(`واتساب: ${p.whatsapp}`);if(p.email)details.push(p.email);if(p.website)details.push(p.website);details.push(...String(p.extra||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean));return `<div class="receipt-provider"><span>Powered by ${esc(p.name||'Elhafez Technology')}${phone?` • ${esc(phone)}`:''}</span>${details.map(x=>`<small>${esc(x)}</small>`).join('')}</div>`}
function receiptLogoSrc(v){const x=String(v||'').trim();return /^data:image\/(png|jpeg|jpg|webp);base64,/i.test(x)?x:''}
function receiptLogoFallback(name){const n=String(name||'ص').trim();return esc((n[0]||'ص').toUpperCase())}
function imageFileToReceiptData(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(!/^image\/(png|jpeg|jpg|webp)$/i.test(file.type||'')){reject(new Error('اختر صورة PNG أو JPG أو WEBP'));return}if(file.size>5*1024*1024){reject(new Error('حجم الشعار يجب ألا يتجاوز 5MB'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('تعذر قراءة ملف الشعار'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('ملف الشعار غير صالح'));img.onload=()=>{const max=512,ratio=Math.min(1,max/Math.max(img.width||1,img.height||1)),w=Math.max(1,Math.round(img.width*ratio)),h=Math.max(1,Math.round(img.height*ratio)),c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);resolve(c.toDataURL('image/png'))};img.src=String(reader.result||'')};reader.readAsDataURL(file)})}
Object.assign(A,{receiptLogoSrc,receiptLogoFallback,imageFileToReceiptData});
function receiptMarkup(s){
 const st=A.state.settings||{},businessRaw=st.receiptBusinessName||st.pharmacyName||'الصيدلية',business=esc(businessRaw),branch=esc(st.branchName||''),customer=esc(s.customerName||'بيع نقدي'),logo=receiptLogoSrc(st.receiptLogoData),phone=esc(st.receiptPhone??st.phone??''),address=esc(st.receiptAddress??st.address??''),tax=esc(st.receiptTaxNumber??st.taxNumber??''),commercial=esc(st.receiptCommercialRegister??st.commercialRegister??''),extra=esc(st.receiptExtraInfo||'');
 const info=[];if(st.receiptShowPhone!==false&&phone)info.push(`الهاتف: ${phone}`);if(st.receiptShowAddress!==false&&address)info.push(address);if(st.receiptShowTaxNumber!==false&&tax)info.push(`الرقم الضريبي: ${tax}`);if(st.receiptShowCommercialRegister!==false&&commercial)info.push(`السجل التجاري: ${commercial}`);if(extra)info.push(extra);
 const logoHtml=logo?`<img src="${logo}" alt="${business}">`:`<span class="receipt-logo-fallback" aria-hidden="true">${receiptLogoFallback(businessRaw)}</span>`;
 const providerLine=providerReceiptLine();
 return `<div class="receipt"><div class="receipt-head"><div class="receipt-brand receipt-customer-brand">${logoHtml}<div><b>${business}</b>${branch?`<small>${branch}</small>`:''}</div></div>${info.length?`<div class="receipt-business-info">${info.map(x=>`<div>${x}</div>`).join('')}</div>`:''}<div class="receipt-meta"><span>فاتورة: <b>${esc(s.no)}</b></span><span>التاريخ: <b>${A.fmtDT(s.at)}</b></span><span>العميل: <b>${customer}</b></span><span>الكاشير: <b>${esc(s.userName||A.state.user?.name||'')}</b></span></div></div><table><thead><tr><th>الصنف</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${(s.lines||[]).map(l=>`<tr><td>${esc(l.name)}</td><td>${num(l.qty)} ${unitLabel(l.unit)}</td><td>${money(l.unitPrice)}</td><td>${money(l.lineTotal||l.qty*l.unitPrice)}</td></tr>`).join('')}</tbody></table><div class="receipt-totals"><div><span>الإجمالي</span><b>${money(s.subtotal)}</b></div>${num(s.discount)>0?`<div><span>خصم</span><b>-${money(s.discount)}</b></div>`:''}${num(s.pointsDiscount)>0?`<div><span>نقاط</span><b>-${money(s.pointsDiscount)}</b></div>`:''}${num(s.contractDiscount)>0?`<div><span>خصم تعاقد</span><b>-${money(s.contractDiscount)}</b></div>`:''}${num(s.deliveryFee)>0?`<div><span>رسوم التوصيل</span><b>${money(s.deliveryFee)}</b></div>`:''}<div class="grand"><span>المطلوب</span><b>${money(s.total)}</b></div><div><span>الدفع</span><b>${esc(s.paymentLabel||s.payment||'')}</b></div></div><div class="receipt-foot">${esc(st.receiptFooter||'شكرًا لزيارتكم')}</div>${providerLine}</div>`
}
function saleShareText(s){const name=A.state.settings?.pharmacyName||A.state.settings?.businessName||'الصيدلية',items=(s.lines||[]).map(x=>`${x.name||x.productName||'صنف'} × ${num(x.qty||x.packs||1)}`).join('، ');return `${name}\nفاتورة: ${s.no}\nالتاريخ: ${A.fmtDT(s.at)}\n${items?`الأصناف: ${items}\n`:''}الإجمالي: ${money(s.total)}\nشكرًا لتعاملكم معنا`}
async function fetchSalePdf(s){if(!window.PharmaRemote?.enabled||!s?.id)throw new Error('PDF يحتاج اتصالًا بالخادم وفاتورة محفوظة');const r=await fetch(window.PharmaRemote.salePdfUrl(s.id),{credentials:'same-origin'});if(!r.ok){let b={};try{b=await r.json()}catch{}const e=new Error(b.error||`HTTP_${r.status}`);e.body=b;throw e}const type=r.headers.get('content-type')||'',blob=await r.blob();if(!type.includes('application/pdf')||blob.size<500)throw new Error('ملف PDF الناتج غير صالح');return new File([blob],`Elhafez-Pharmacy-${s.no||'Invoice'}.pdf`,{type:'application/pdf'})}
function downloadFile(file){const a=document.createElement('a'),url=URL.createObjectURL(file);a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function downloadSalePdf(s){const page=state.page;clearToast();try{const file=await fetchSalePdf(s);downloadFile(file);if(state.page===page)toast(`تم تنزيل ${file.name}`,'success')}catch(e){if(state.page===page)toast(window.PharmaRemote?.friendlyError?.(e)||e.message||'تعذر إنشاء PDF','danger')}}
async function shareSalePdf(s){const page=state.page;clearToast();try{const file=await fetchSalePdf(s);if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({title:`فاتورة ${s.no}`,files:[file]});if(state.page===page)toast('تم تسليم ملف PDF لنافذة المشاركة','success')}else{downloadFile(file);if(state.page===page)toast('مشاركة الملفات غير مدعومة هنا؛ تم تنزيل PDF الحقيقي بدلًا منها','info')}}catch(e){if(e?.name!=='AbortError'&&state.page===page)toast(window.PharmaRemote?.friendlyError?.(e)||e.message||'تعذر مشاركة PDF','danger')}}
async function shareSaleText(s){const page=state.page,text=saleShareText(s);clearToast();try{if(navigator.share){await navigator.share({title:`فاتورة ${s.no}`,text});if(state.page===page)toast('تم تسليم نص الفاتورة لنافذة المشاركة','success');return}await navigator.clipboard.writeText(text);if(state.page===page)toast('تم نسخ نص الفاتورة للمشاركة','success')}catch(e){if(e?.name!=='AbortError'&&state.page===page)toast('تعذر مشاركة النص. يمكنك نسخه أو استخدام WhatsApp.','warn')}}
function whatsappSale(s){clearToast();const phone=String(s.customerPhone||s.phone||'').replace(/[^0-9]/g,'').replace(/^0(?=1[0125])/, '20');if(!phone){toast('لا يوجد رقم هاتف محفوظ لهذا العميل. أضف رقم العميل ثم أعد إرسال رسالة WhatsApp.','warn');return}const w=window.open(`https://wa.me/${phone}?text=${encodeURIComponent(saleShareText(s))}`,'_blank','noopener');if(!w)toast('تعذر فتح WhatsApp. اسمح للنظام بفتح النافذة ثم أعد المحاولة.','warn')}
async function showReceipt(s){if(!s)return;clearToast();await refreshProviderBrand();modal(`فاتورة ${s.no}`,receiptMarkup(s),`<button class="btn" data-close>إغلاق</button><button id="pdfReceiptBtn" class="btn info">تنزيل PDF A4</button><button id="sharePdfReceiptBtn" class="btn info">مشاركة PDF</button><button id="printReceiptBtn" class="btn success">طباعة إيصال حراري</button><button id="shareReceiptBtn" class="btn">مشاركة نص</button><button id="waReceiptBtn" class="btn">WhatsApp نص</button>`);A.$('#printReceiptBtn').onclick=()=>printReceipt(s);A.$('#pdfReceiptBtn').onclick=()=>downloadSalePdf(s);A.$('#sharePdfReceiptBtn').onclick=()=>shareSalePdf(s);A.$('#shareReceiptBtn').onclick=()=>shareSaleText(s);A.$('#waReceiptBtn').onclick=()=>whatsappSale(s)}
function receiptPrintDocument(s){const width=String(A.state.settings?.receiptWidth||'80')==='58'?58:80;return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${esc(s.no)}</title><style>@page{size:${width}mm auto;margin:2.5mm}html,body{width:${width-5}mm;margin:0;padding:0;background:#fff;color:#111}body{font-family:Arial,Tahoma,sans-serif}.receipt{width:100%;max-width:none;margin:0}.receipt-head{text-align:center;font-size:9.5px;line-height:1.55}.receipt-head h2{margin:4px 0;font-size:14px}.receipt-brand{display:flex;align-items:center;justify-content:center;gap:6px;margin-bottom:5px}.receipt-brand img,.receipt-logo-fallback{width:32px;height:32px;border-radius:7px;object-fit:contain}.receipt-logo-fallback{display:grid;place-items:center;border:1px solid #bbb;font-weight:800;font-size:16px}.receipt-brand div{text-align:right}.receipt-brand b,.receipt-brand small{display:block}.receipt-brand b{font-size:11px}.receipt-brand small{font-size:7px}.receipt-business-info{text-align:center;font-size:7.5px;line-height:1.45;margin:3px 0 5px}.receipt-meta{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin:6px 0;font-size:7.5px}.receipt-meta span{border:1px solid #ddd;border-radius:4px;padding:3px}table{width:100%;border-collapse:collapse;margin:7px 0;font-size:8px;table-layout:fixed}th,td{padding:4px 2px;border-bottom:1px dashed #bbb;text-align:right;overflow-wrap:anywhere}tr{break-inside:avoid;page-break-inside:avoid}th:first-child,td:first-child{width:40%}.receipt-totals>div{display:flex;justify-content:space-between;padding:3px 0;font-size:9px}.receipt-totals .grand{font-size:12px;font-weight:800;border-top:1px solid #111;margin-top:3px;padding-top:5px}.receipt-foot{text-align:center;margin-top:10px;font-size:8px}.receipt-provider{text-align:center;border-top:1px dashed #ccc;margin-top:7px;padding-top:5px;color:#666;font-size:6.5px;line-height:1.4}.receipt-provider span,.receipt-provider small{display:block}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>${receiptMarkup(s)}</body></html>`}
async function printReceipt(s){const page=state.page;clearToast();await refreshProviderBrand(true);const html=receiptPrintDocument(s);if(window.AndroidBridge?.printHtml){try{window.AndroidBridge.printHtml(`فاتورة ${s.no||''}`,html);if(state.page===page)toast('تم إرسال الإيصال إلى خدمة الطباعة. أكمل الطباعة من نافذة الجهاز.','info');return}catch{if(state.page===page)toast('تعذر إرسال الإيصال لخدمة الطباعة','danger');return}}let frame=document.getElementById('receiptPrintFrame');if(frame)frame.remove();frame=document.createElement('iframe');frame.id='receiptPrintFrame';frame.setAttribute('aria-hidden','true');Object.assign(frame.style,{position:'fixed',inset:'auto 0 0 auto',width:'1px',height:'1px',border:'0',opacity:'0',pointerEvents:'none'});document.body.appendChild(frame);const doc=frame.contentDocument;doc.open();doc.write(html);doc.close();frame.onload=()=>{setTimeout(()=>{try{frame.contentWindow.focus();frame.contentWindow.print();if(state.page===page)toast('تم فتح نافذة الطباعة الحرارية. أكمل الطباعة من المتصفح.','info')}catch{if(state.page===page)toast('تعذر فتح نافذة الطباعة','danger')}setTimeout(()=>frame.remove(),2500)},120)}}
function printTestReceipt(){const now=new Date().toISOString(),sample={no:'TEST-001',at:now,customerName:'إيصال اختبار',userName:A.state.user?.name||'مدير النظام',lines:[{name:'Panadol Extra — Sample',qty:1,unit:'pack',unitPrice:95,lineTotal:95},{name:'Vitamin C 500mg — Sample',qty:2,unit:'pack',unitPrice:68,lineTotal:136}],subtotal:231,total:231,payment:'cash',paymentLabel:'نقدي'};printReceipt(sample)}
A.printReceipt=printReceipt;A.printTestReceipt=printTestReceipt;

async function returnSale(saleId){
 if(!A.canAction?.('returns')){toast('لا توجد صلاحية لتنفيذ المرتجعات','danger');return}
 const s=await get('sales',saleId);if(!s||s.status==='returned')return;const returned=s.returnedQtyByLine||{},canPayout=A.canAction?.('refund');
 const refundOptions=[`<option value="original">نفس طريقة الدفع الأصلية</option>`,...(canPayout?[`<option value="cash">استرداد نقدي</option>`,`<option value="card">إرجاع على البطاقة</option>`,`<option value="wallet">إرجاع للمحفظة</option>`]:[]),...(s.customerId?[`<option value="customer_credit">رصيد دائن للعميل</option>`]:[])].join('');
 modal(`مرتجع ${s.no}`,`<form id="returnSaleForm" class="return-lines">${(s.lines||[]).map((l,i)=>{const rem=Math.max(0,num(l.qty)-num(returned[i]));return `<label class="return-line"><span><b>${esc(l.name)}</b><small>المباع ${num(l.qty)} ${unitLabel(l.unit)} • المتاح للمرتجع ${rem}</small></span><input name="line_${i}" type="number" min="0" max="${rem}" step="1" value="0" ${rem<=0?'disabled':''}></label>`}).join('')}<div class="form-grid two section-gap-sm"><label>سبب المرتجع<select name="reason" required><option value="">اختر السبب</option><option>إلغاء/خطأ في الصرف</option><option>رفض العميل قبل الاستخدام</option><option>عيب ظاهر في العبوة</option><option>أخرى</option></select></label><label>التصرف في الدواء<select name="disposition" required><option value="quarantine">حجر وفحص — الافتراضي الآمن</option><option value="resalable">صالح لإعادة البيع بعد الفحص</option><option value="damaged">تالف</option><option value="expired">منتهي الصلاحية</option></select></label><label>طريقة التسوية<select name="refundMethod" required>${refundOptions}</select></label><label>ملاحظة<textarea name="note" rows="2" placeholder="تفاصيل إضافية عند الحاجة"></textarea></label><label id="resaleReviewRow" class="check-row span-all hidden"><input type="checkbox" name="resaleReviewed"> تم فحص الدواء وظروف التخزين والعبوة بواسطة موظف مخول وثبتت صلاحيته لإعادة البيع</label></div></form><div class="notice warn">المرتجع لا يعود للبيع تلقائيًا. الوضع الافتراضي هو الحجر حتى يتم تحديد حالته بوضوح.</div>`,`<button class="btn" data-close>إلغاء</button><button id="confirmReturnSale" class="btn danger">اعتماد المرتجع</button>`);
 const form=A.$('#returnSaleForm'),disp=form.querySelector('[name=disposition]'),review=A.$('#resaleReviewRow');disp.onchange=()=>review.classList.toggle('hidden',disp.value!=='resalable');
 A.$('#confirmReturnSale').onclick=async()=>{
   if(window.PharmaRemote?.enabled&&!window.PharmaRemote.inAtomic())return window.PharmaRemote.atomic(()=>A.$('#confirmReturnSale').onclick(),'sale_return');
   if(!form.reportValidity())return;const fd=new FormData(form),reason=String(fd.get('reason')||'').trim(),disposition=String(fd.get('disposition')||'quarantine'),refundMethod=String(fd.get('refundMethod')||'original'),note=String(fd.get('note')||'').trim();
   if(disposition==='resalable'&&fd.get('resaleReviewed')!=='on'){toast('إعادة الدواء للبيع تحتاج تأكيد الفحص','danger');return}
   if(['cash','card','wallet'].includes(refundMethod)&&!canPayout){toast('لا توجد صلاحية لاسترداد الأموال','danger');return}
   const F=window.ElhafezFinance,derived=F.computeSale(s.lines||[],{discount:s.discount,pointsDiscount:s.pointsDiscount,contractDiscount:s.contractDiscount,deliveryFee:s.deliveryFee,pricesIncludeTax:s.pricesIncludeTax!==false,taxRegistered:s.taxRegistered!==false}),request=[];let returnGross=0,returnNet=0,returnTax=0;
   for(let i=0;i<(s.lines||[]).length;i++){const q=num(fd.get(`line_${i}`));if(q>0){const original=s.lines[i],rem=Math.max(0,num(original.qty)-num(returned[i]));if(q>rem){toast('كمية المرتجع أكبر من المتاح','danger');return}const line={...original,...derived.lines[i]},amounts=F.returnAmounts(line,q);request.push({i,line,qty:q,amounts});returnGross=F.money(returnGross+amounts.gross);returnNet=F.money(returnNet+amounts.net);returnTax=F.money(returnTax+amounts.tax)}}
   if(!request.length){toast('أدخل كمية مرتجع واحدة على الأقل','danger');return}
   const batchReturned=s.returnedBaseByBatch||{},restorePlan=[];let originalReturnedCost=0;
   for(const r of request){let need=r.qty*num(r.line.factor||1);for(const x of r.line.allocations||[]){if(need<=0)break;const used=num(batchReturned[x.batchId]),available=Math.max(0,num(x.qtyBase)-used),take=Math.min(need,available);if(take>0){restorePlan.push({lineIndex:r.i,line:r.line,sourceBatchId:x.batchId,qtyBase:take,costPerBase:num(x.costPerBase)});need-=take;originalReturnedCost+=take*num(x.costPerBase)}}if(need>0.0001){toast(`تعذر تحديد التشغيلة الأصلية للمرتجع: ${r.line.name}`,'danger');return}}
   for(const r of request)returned[r.i]=num(returned[r.i])+r.qty;
   const fully=(s.lines||[]).every((l,i)=>num(returned[i])>=num(l.qty)),deliveryRefund=fully&&!s.returnedDeliveryFee?num(s.deliveryFee):0,refund=F.money(returnGross+deliveryRefund),restoredCost=['resalable','quarantine'].includes(disposition)?F.money(originalReturnedCost):0;
   const returnId=id('ret'),returnAt=new Date().toISOString(),inspections=[];
   for(const x of restorePlan){const source=await get('batches',x.sourceBatchId);if(!source){toast('إحدى التشغيلات الأصلية غير موجودة','danger');return}let target=source;
     if(disposition==='resalable'){source.qtyBase=num(source.qtyBase)+x.qtyBase;await put('batches',source)}else{target={id:id('rbat'),productId:x.line.productId,branchId:s.branchId||A.state.settings?.branchId||null,batchNo:source.batchNo,expiry:source.expiry,qtyBase:x.qtyBase,costPerBase:disposition==='quarantine'?x.costPerBase:0,originalCostPerBase:x.costPerBase,supplierId:source.supplierId||null,status:disposition==='quarantine'?'quarantine':disposition==='expired'?'expired':'waste',sourceBatchId:source.id,returnId,receivedAt:returnAt};await put('batches',target)}
     batchReturned[x.sourceBatchId]=num(batchReturned[x.sourceBatchId])+x.qtyBase;await A.stockMove(x.line.productId,target.id,x.qtyBase,'sale_return',`R-${s.no}`,`${reason} — ${disposition}`);inspections.push({productId:x.line.productId,batchId:target.id,sourceBatchId:x.sourceBatchId,qtyBase:x.qtyBase,disposition,reason,inspectedBy:A.state.user?.name||'',inspectedAt:returnAt});
   }
   s.returnedQtyByLine=returned;s.returnedBaseByBatch=batchReturned;s.returnedAmount=F.money(num(s.returnedAmount)+refund);s.returnedCost=F.money(num(s.returnedCost)+originalReturnedCost);s.returnedTax=F.money(num(s.returnedTax)+returnTax);s.returnedDeliveryFee=F.money(num(s.returnedDeliveryFee)+deliveryRefund);s.status=fully?'returned':'partial_return';s.returnedAt=returnAt;
   const settlementCredits=[];
   if(refundMethod==='customer_credit'){
     if(!s.customerId){toast('الرصيد الدائن يحتاج عميلًا مسجلًا','danger');return}const c=await get('customers',s.customerId);c.creditBalance=F.money(num(c.creditBalance)+refund);await put('customers',c);settlementCredits.push({accountCode:'2050',account:'أرصدة دائنة للعملاء',debit:0,credit:refund});
   }else if(s.payment==='credit'&&refundMethod==='original'){
     const c=s.customerId?await get('customers',s.customerId):null,outstanding=Math.max(0,num(s.creditBalance||Math.max(0,num(s.total)-num(s.returnedAmount)+refund))),arReduction=Math.min(refund,outstanding),excess=F.money(refund-arReduction);s.creditBalance=F.money(outstanding-arReduction);if(c){c.balance=Math.max(0,F.money(num(c.balance)-arReduction));if(excess>0)c.creditBalance=F.money(num(c.creditBalance)+excess);await put('customers',c)}if(arReduction>0)settlementCredits.push({accountCode:'1100',account:'عملاء',debit:0,credit:arReduction});if(excess>0)settlementCredits.push({accountCode:'2050',account:'أرصدة دائنة للعملاء',debit:0,credit:excess});
   }else if(s.payment==='insurance'&&refundMethod==='original'){
     if(!canPayout&&num(s.customerPay)>0){toast('مرتجع التأمين يتضمن استردادًا ماليًا ويحتاج صلاحية الاسترداد','danger');return}const originalTotal=Math.max(0.01,num(s.total)),customerPart=F.money(refund*num(s.customerPay)/originalTotal),claimPart=F.money(refund-customerPart);if(customerPart>0){await A.cashMove('sale_return',customerPart,`R-${s.no}`,`رد تحمل عميل ${s.no}`,'cash','out');settlementCredits.push({accountCode:'1000',account:'الخزينة',debit:0,credit:customerPart})}if(claimPart>0){settlementCredits.push({accountCode:'1150',account:'مطالبات التأمين',debit:0,credit:claimPart});const claims=await all('claims'),cl=claims.find(x=>x.saleId===s.id&&x.status!=='cancelled');if(cl){cl.amount=Math.max(0,F.money(num(cl.amount)-claimPart));if(fully)cl.status='cancelled';cl.adjustedAt=returnAt;await put('claims',cl)}}
   }else if(s.payment==='split'&&refundMethod==='original'){
     if(!canPayout){toast('الاسترداد على وسائل الدفع يحتاج صلاحية الاسترداد','danger');return}const original=Object.entries(s.splitPayments||{}).filter(([,v])=>num(v)>0),origTotal=original.reduce((a,[,v])=>a+num(v),0)||num(s.total);let allocated=0;for(let i=0;i<original.length;i++){const [m,v]=original[i],amt=i===original.length-1?F.money(Math.max(0,refund-allocated)):F.money(refund*num(v)/origTotal);allocated=F.money(allocated+amt);if(amt>0){await A.cashMove('sale_return',amt,`R-${s.no}`,`مرتجع مختلط ${s.no}`,m,'out');settlementCredits.push({accountCode:m==='cash'?'1000':'1020',account:m==='cash'?'الخزينة':'وسائل تحصيل',debit:0,credit:amt})}}
   }else{
     const method=refundMethod==='original'?s.payment:refundMethod;if(!canPayout){toast('لا توجد صلاحية لاسترداد الأموال','danger');return}await A.cashMove('sale_return',refund,`R-${s.no}`,`مرتجع فاتورة ${s.no}`,method,'out');settlementCredits.push({accountCode:method==='cash'?'1000':method==='bank'?'1010':'1020',account:method==='cash'?'الخزينة':method==='bank'?'البنك':'وسائل تحصيل',debit:0,credit:refund});
   }
   await put('sales',s);await put('returns',{id:returnId,type:'sale_return',saleId:s.id,saleNo:s.no,at:returnAt,total:refund,net:returnNet,tax:returnTax,deliveryRefund,cost:originalReturnedCost,costRestored:restoredCost,reason,disposition,refundMethod,note,inspectedBy:A.state.user?.name||'',inspectedAt:returnAt,items:request.map(r=>({lineIndex:r.i,productId:r.line.productId,name:r.line.name,qty:r.qty,unit:r.line.unit,gross:r.amounts.gross,net:r.amounts.net,tax:r.amounts.tax})),inspections});
   const journalLines=[{accountCode:'4010',account:'مردودات المبيعات',debit:returnNet,credit:0},...(returnTax>0?[{accountCode:'2100',account:'ضريبة مخرجات مستحقة',debit:returnTax,credit:0}]:[]),...(deliveryRefund>0?[{accountCode:'4100',account:'إيرادات التوصيل',debit:deliveryRefund,credit:0}]:[]),...settlementCredits];
   if(restoredCost>0)journalLines.push({accountCode:'1200',account:'المخزون',debit:restoredCost,credit:0},{accountCode:'5000',account:'تكلفة البضاعة المباعة',debit:0,credit:restoredCost});else if(originalReturnedCost>0)journalLines.push({accountCode:'6100',account:'خسائر التلف والانتهاء',debit:originalReturnedCost,credit:0},{accountCode:'5000',account:'تكلفة البضاعة المباعة',debit:0,credit:originalReturnedCost});
   await A.journal(`R-${s.no}-${Date.now()}`,'sale_return',journalLines,`مرتجع ${s.no} — ${reason}`);await audit('مرتجع بيع',`${s.no} — ${refund} — ${disposition}`);closeModal();toast(disposition==='resalable'?'تم تسجيل المرتجع وإعادة الكمية بعد الفحص':'تم تسجيل المرتجع وفصل الكمية عن المخزون القابل للبيع');A.render();
 }
}

