register('reorder',async()=>{
 const [products,sales,purchases,suppliers]=await Promise.all([all('products'),all('sales'),all('purchases'),all('suppliers')]),since=Date.now()-30*86400000,rows=[],supMap=Object.fromEntries(suppliers.map(s=>[s.id,s]));
 for(const p of products){const pk=packSize(p),stockBase=await stockFor(p.id,{sellableOnly:true}),stockPacks=stockBase/pk;let soldBase=0;for(const s of sales.filter(s=>new Date(s.at).getTime()>=since&&s.status!=='returned'))for(const l of s.lines||[])if(l.productId===p.id)soldBase+=num(l.qty)*num(l.factor||pk);const avgDailyPacks=(soldBase/pk)/30,targetDays=num(A.state.settings?.reorderTargetDays)||14,min=num(p.minStock),target=Math.max(min,avgDailyPacks*targetDays),suggest=Math.max(0,Math.ceil(target-stockPacks)),daysCover=avgDailyPacks>0?stockPacks/avgDailyPacks:999,hist=purchases.filter(x=>x.productId===p.id&&num(x.packCost)>0),best=hist.slice().sort((a,b)=>num(a.packCost)-num(b.packCost))[0]||null,last=hist.slice().sort((a,b)=>new Date(b.at)-new Date(a.at))[0]||null;rows.push({p,stockPacks,avgDailyPacks,suggest,daysCover,best,last})}
 rows.sort((a,b)=>b.suggest-a.suggest||a.daysCover-b.daysCover);
 A.$('#content').innerHTML=`${pageHead('النواقص والشراء الذكي','اقتراح 14 يوم اعتمادًا على مبيعات آخر 30 يوم والحد الأدنى')}<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>الصنف</th><th>المخزون/علبة</th><th>متوسط يومي</th><th>تغطية بالأيام</th><th>الحد الأدنى</th><th>أفضل مورد تاريخيًا</th><th>آخر سعر شراء</th><th>المقترح شراءه</th><th>الحالة</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.p.name)}</b></td><td>${x.stockPacks.toFixed(1)}</td><td>${x.avgDailyPacks.toFixed(2)}</td><td>${x.daysCover===999?'—':x.daysCover.toFixed(1)}</td><td>${num(x.p.minStock)}</td><td>${x.best?`${esc(supMap[x.best.supplierId]?.name||x.best.supplierName||'-')} • ${money(x.best.packCost)}`:'—'}</td><td>${x.last?money(x.last.packCost):'—'}</td><td><b>${x.suggest}</b></td><td>${x.suggest>0?badge('يحتاج شراء',x.daysCover<5?'danger':'warn'):badge('جيد','ok')}</td></tr>`).join('')}</tbody></table></div></div>`;
});
